@cache
def _dom(name, color):
    svg = (f'<svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 16 16">'
           f'<path fill="{color}" d="{OCTICONS[name]}"/></svg>').encode()
    dom = skia.SVGDOM.MakeFromStream(skia.MemoryStream(svg, True))
    if dom is None:
        raise RuntimeError(f"skia cannot parse the octicon {name}")
    return dom


def octicon(canvas, name, x, y, size, color, alpha=1.0):
    """An octicon `size` px square with its top-left corner at (x, y)."""
    if alpha <= 0.002:
        return
    dom = _dom(name, color)
    count = canvas.save()
    canvas.translate(x, y)
    canvas.scale(size / 16, size / 16)
    canvas.saveLayerAlpha(skia.Rect.MakeWH(16, 16), round(alpha * 255))
    dom.render(canvas)
    canvas.restoreToCount(count)


def linear_status(canvas, kind, x, y, r, alpha, colors):
    """Linear's status ring, centred on (x, y): "todo" is a thin grey ring, "progress" a yellow
    ring with a partial pie fill, "done" a filled indigo circle with a check. `colors` is the
    Linear theme (todo grey, yellow, accent)."""
    if alpha <= 0.002:
        return
    if kind == "todo":
        canvas.drawCircle(x, y, r, gfx.stroke_paint(colors.todo, 1.8, alpha, cap="butt"))
    elif kind == "progress":
        canvas.drawCircle(x, y, r, gfx.stroke_paint(colors.yellow, 1.8, alpha, cap="butt"))
        path = skia.Path()
        path.moveTo(x, y)
        path.arcTo(skia.Rect.MakeLTRB(x - r + 3.2, y - r + 3.2, x + r - 3.2, y + r - 3.2), -90, 150, False)
        path.close()
        canvas.drawPath(path, gfx.fill_paint(colors.yellow, alpha))
    elif kind == "done":
        canvas.drawCircle(x, y, r, gfx.fill_paint(colors.accent, alpha))
        p = skia.Path()
        p.moveTo(x - r * 0.45, y)
        p.lineTo(x - r * 0.12, y + r * 0.35)
        p.lineTo(x + r * 0.5, y - r * 0.35)
        canvas.drawPath(p, gfx.stroke_paint("#ffffff", 1.8, alpha))
    else:
        raise ValueError(f"unknown status {kind!r}")


def linear_priority_none(canvas, x, y, color, alpha):
    """Linear's "No priority" icon: three short dashes."""
    if alpha <= 0.002:
        return
    p = gfx.stroke_paint(color, 1.6, alpha, cap="round")
    for i in range(3):
        canvas.drawLine(x + i * 5 - 5, y, x + i * 5 - 2.4, y, p)


def slack_check(canvas, x, y, size, alpha):
    """The :white_check_mark: emoji as a green rounded square with a white tick, centred."""
    if alpha <= 0.002:
        return
    rr = gfx.rrect(x - size / 2, y - size / 2, size, size, size * 0.22)
    canvas.drawRRect(rr, gfx.fill_paint("#3fb46b", alpha))
    p = skia.Path()
    p.moveTo(x - size * 0.28, y + size * 0.02)
    p.lineTo(x - size * 0.08, y + size * 0.24)
    p.lineTo(x + size * 0.3, y - size * 0.22)
    canvas.drawPath(p, gfx.stroke_paint("#ffffff", max(2.0, size * 0.13), alpha))
